() => { 
  // Find the preprocessors section and explore it
  const links = Array.from(document.querySelectorAll('a'));
  return links.filter(l => l.textContent.toLowerCase().includes('tokenizer')).slice(0, 20).map(l => ({text: l.textContent.trim().substring(0, 100), href: l.href}));
}

() => { 
  const links = Array.from(document.querySelectorAll('a'));
  const tokenizerLinks = links.filter(l => l.textContent.toLowerCase().includes('tokenizer'));
  return tokenizerLinks.slice(0, 30).map(l => ({text: l.textContent.trim().substring(0, 100), href: l.getAttribute('href')}));
}

() => { 
  const main = document.querySelector('main') || document.querySelector('[role="main"]') || document.body;
  const headings = Array.from(main.querySelectorAll('h1, h2, h3, h4'));
  return headings.map(h => ({tag: h.tagName, text: h.textContent.trim()}));
}

() => { 
  // Try to find headings - alternative selector
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4, h5, h6'));
  return headings.map(h => ({tag: h.tagName, text: h.textContent.trim().substring(0, 100)}));
}

() => { 
  const article = document.querySelector('article') || document.querySelector('[role="article"]');
  if (article) {
    return {found: 'article', text: article.innerText.substring(0, 3000)};
  }
  const main = document.querySelector('main');
  if (main) {
    return {found: 'main', text: main.innerText.substring(0, 3000)};
  }
  return {found: 'none', text: document.body.innerText.substring(0, 3000)};
}

() => { 
  const all = Array.from(document.querySelectorAll('h1, h2, h3, h4'));
  return all.length;
}

() => { 
  // Get all text content with structure
  const article = document.querySelector('article') || document.querySelector('main article');
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4'));
  return {
    headings: headings.map(h => ({tag: h.tagName, text: h.textContent.trim()})),
    headingCount: headings.length,
    hasArticle: !!article,
    bodyTextLength: document.body.innerText.length
  };
}

() => {
  // Find all code blocks that contain add_tokens
  const codeBlocks = Array.from(document.querySelectorAll('pre, code'));
  const result = codeBlocks.filter(c => c.textContent.includes('add_tokens')).map(c => c.textContent.trim().substring(0, 500));
  return { count: codeBlocks.filter(c => c.textContent.includes('add_tokens')).length, examples: result };
}

() => {
  const allText = document.body.innerText;
  const idx = allText.indexOf('add_tokens');
  if (idx === -1) return 'add_tokens not found';
  return allText.substring(Math.max(0, idx - 200), idx + 2000);
}

() => {
  // Find links that mention "Tokenizer" and look at the href
  const links = Array.from(document.querySelectorAll('a'));
  const matches = links.filter(l => {
    const text = l.textContent.trim();
    return text === 'Tokenizer' || text.toLowerCase().includes('tokenizer') && l.id;
  });
  return matches.slice(0, 10).map(l => ({text: l.textContent.trim().substring(0, 50), href: l.getAttribute('href'), id: l.id}));
}
